    EZTR_Basic_ReplaceText(0x0035, 0x02, 0x00, 0x35, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast " "\x01" "Wundererbsen " "\x00" "erhalten!" "\x18" "\x11" "\x13" "\x13" "\x12" "Finde einen Flecken " "\x01" "weicher Erde" "\x00" "," "\x11" "und dr" "\xAC" "cke " "\x04" "\xB2" "\x00" ", um die Erbsen zu" "\x11" "pflanzen. Wer wei" "\x96" ", was die Erde" "\x11" "hervorbringen wird?!?" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0036, 0x02, 0x00, 0x1A, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du erh" "\x9A" "ltst eine " "\x01" "Krabbelmine" "\x00" "!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "Im " "\x04" "Inventar" "\x00" " kannst du sie auf " "\x04" "\xB8" "\x00" "," "\x11" "\x04" "\xB7" "\x00" " oder " "\x04" "\xB9" "\x00" " platzieren." "\x11" "\x12" "Dr" "\xAC" "cke " "\x04" "\xB2" "\x00" ", um eine dieser" "\x11" "Kletterbomben scharf zu machen." "\x11" "Dr" "\xAC" "cke nochmals " "\x04" "\xB2" "\x00" ", um die Mine" "\x11" "loszuschicken." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0037, 0x00, 0x03, 0x0F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0038, 0x02, 0x01, 0x38, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Dein Kokiri-Schwert erfuhr die" "\x11" "Kraft von Glut und Stahl! Sein" "\x11" "neuer Name soll fortan" "\x11" "\x01" "Elfenschwert " "\x00" "sein!" "\x18" "\x10" "Die schimmernde Klinge dieses" "\x11" "Schwertes schneidet sch" "\x9A" "rfer als" "\x11" "der eisige Odem des Winters." "\x01" " " "\x11" "100 mal " "\x00" "kannst du es einsetzen," "\x10" "bevor seine Schneide ihre Kraft" "\x11" "wieder verliert. " "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0039, 0x02, 0x01, 0x39, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Dein Elfenschwert erfuhr die" "\x11" "Macht der ewigen Elemente. Sein" "\x11" "neuer Name soll fortan" "\x11" "\x01" "Schmirgelklinge " "\x00" "sein!" "\x18" "\x10" "Durch die Kunst des Schmiedes" "\x11" "trennt diese edle Klinge Licht von" "\x11" "Schatten. Selbst die M" "\x9A" "chte der" "\x11" "Finsternis verm" "\xA8" "gen es nicht," "\x10" "den Geist der Gerechtigkeit aus" "\x11" "dem Stahl dieses Schwertes zu " "\x11" "vertreiben! " "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x003A, 0x02, 0x00, 0x1A, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du erh" "\x9A" "ltst " "\x01" "5 Krabbelminen" "\x00" "!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "Im " "\x04" "Inventar" "\x00" " kannst du sie auf " "\x04" "\xB8" "\x00" "," "\x11" "\x04" "\xB7" "\x00" " oder " "\x04" "\xB9" " " "\x00" "platzieren." "\x11" "\x12" "Dr" "\xAC" "cke " "\x04" "\xB2" "\x00" ", um eine dieser" "\x11" "Kletterbomben scharf zu machen." "\x11" "Dr" "\xAC" "cke nochmals " "\x04" "\xB2" "\x00" ", um die Mine" "\x11" "loszuschicken." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x003B, 0x02, 0x01, 0x3B, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast das " "\x01" "Feenschwert" "\x11" "\x00" "erhalten!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "Um es einzusetzen, musst du dich" "\x11" "zuvor mit " "\x04" "\xB2" "\x00" " bewaffnen." "\x10" "Die filigranen Umrisse schwarzer" "\x11" "Rosen zieren die m" "\x9A" "chtige Klinge," "\x11" "welche die Kr" "\x9A" "fte der Feenwelt" "\x11" "beherbergt." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x003C, 0x02, 0x00, 0x3C, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du erh" "\x9A" "ltst einen " "\x01" "Kleinen" "\x11" "Schl" "\xAC" "ssel" "\x00" "!" "\x18" "\x11" "\x13" "\x12" "Damit " "\xA8" "ffnest du eine" "\x11" "verschlossene T" "\xAC" "r. Du kannst" "\x11" "den Schl" "\xAC" "ssel nur in diesem" "\x11" "Labyrinth einsetzen. " "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x003D, 0x02, 0x00, 0x3D, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast den " "\x01" "Master-Schl" "\xAC" "ssel" "\x11" "\x00" "gefunden!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "Jetzt kannst die T" "\xAC" "r zur Kammer" "\x11" "des Endgegners " "\xA8" "ffnen!" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x003E, 0x02, 0x00, 0x3E, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast die " "\x01" "Karte " "\x00" "gefunden!" "\x18" "\x11" "\x13" "\x13" "\x12" "Dr" "\xAC" "cke START, um die Karte" "\x11" "im Men" "\xAC" " einzusehen. Jene" "\x11" "Bereiche, die du bereits erforscht" "\x11" "hast, erscheinen " "\x03" "blau" "\x00" ". Deine " "\x10" "momentane Position wird durch " "\x11" "eine" "\x05" " blinkende" "\x00" " Fl" "\x9A" "che" "\x05" " " "\x00" "angezeigt." "\x11" "Bewege den " "\xBB" ", um zu einem" "\x11" "anderen Stockwerk zu wechseln. " "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x003F, 0x02, 0x00, 0x3F, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast den " "\x01" "Kompass " "\x00" "gefunden!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "Dieses n" "\xAC" "tzliche Ger" "\x9A" "t enth" "\xAC" "llt" "\x11" "viele versteckte Gegenst" "\x9A" "nde auf" "\x11" "der Karte!" "\xBF" "", NULL);
