    EZTR_Basic_ReplaceText(0x0042, 0x02, 0x01, 0x42, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast das " "\x01" "Auge der Wahrheit" "\x11" "\x00" "erhalten!" "\x18" "\x11" "\x13" "\x12" "Blicke durch die mystische Linse," "\x11" "um Geheimnisse zu sehen, die dem" "\x11" "Auge ansonsten verborgen bleiben." "\x11" "Platziere es auf " "\x04" "\xB2" "\x00" ", um das Auge" "\x10" "einsetzen zu k" "\xA8" "nnen. Das Fenster" "\x11" "zur Wahrheit zehrt aber an deiner" "\x11" "Magieanzeige. Dr" "\xAC" "cke" "\x04" " " "\xB2" "\x00" ", um den" "\x11" "Vorgang wieder zu stoppen." "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x0043, 0x02, 0x01, 0x43, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x17" "Du hast die " "\x01" "Foto-Box" "\x00" " erhalten!" "\x18" "\x11" "\x1F" "\x00" "\x0A" "Dr" "\xAC" "cke " "\x04" "\xB2" "\x00" ", um durch den Sucher" "\x11" "zu blicken. Dr" "\xAC" "cke anschlie" "\x96" "end" "\x11" "\xB0" ", um den Ausl" "\xA8" "ser zu bet" "\x9A" "tigen." "\x10" "Der Film in der Foto-Box reicht" "\x11" "zwar nur f" "\xAC" "r einen Schnappschuss," "\x11" "dieser kann aber jederzeit wieder" "\x11" "ausgetauscht werden." "\xBF" "", NULL);
