    EZTR_Basic_ReplaceText(0x0757, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Wenn du bis " "\x01" "morgen fr" "\xAC" "h" "\x00" " alle " "\x01" "f" "\xAC" "nf" "\x11" "\x00" "von uns finden kannst, verrate ich" "\x11" "dir den geheimen Code. Fertig?" "\xE0" "\xBF" "", NULL);
