    EZTR_Basic_ReplaceText(0x2328, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Der Gebrauch von Masken in die-" "\x11" "sem Laden ist aufgrund vergange-" "\x11" "ner Vorf" "\x9A" "lle untersagt!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2329, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Kafei!" "\x11" "Nein, ich kenne kein Kind mit die-" "\x11" "sem Namen. Ich scherze nicht!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232A, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Wenn du so etwas tr" "\x9A" "gst, findest" "\x11" "du keine ruhige Minute mehr." "\x11" "Ich scherze nicht!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232B, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Hey, das ist niedlich..." "\x11" "Vielleicht kann ich so etwas auch" "\x11" "hier im Laden tragen..." "\x11" "Ich scherze nicht!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Du kannst das Ding abnehmen," "\x11" "hier musst du kein Mitglied sein." "\x11" "Ich scherze nicht!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Nicht " "\xAC" "bel f" "\xAC" "r so einen kleinen" "\x11" "Kerl. Briefe auszutragen ist ein" "\x11" "harter Job." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232E, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Oh! Wer ist denn die Gl" "\xAC" "ckliche?" "\x11" "Meine Gl" "\xAC" "ckw" "\xAC" "nsche!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Hey, f" "\xAC" "hr hier blo" "\x96" " keinen Tanz" "\x11" "auf! Mein Laden ist viel zu klein" "\x11" "f" "\xAC" "r so etwas!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2330, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Das ist ja ein abgefahrenes Ding" "\x11" "auf deinem Kopf. Nimm es ab..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2331, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Das ist krank!" "\x11" "Ich dachte, jemand w" "\x9A" "re gerade" "\x11" "hier durchspaziert." "\x11" "\x12" "Egal, ich muss mich auf die Nacht-" "\x11" "schicht vorbereiten." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2332, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "F" "\xAC" "r einen Parade-Marsch ist es" "\x11" "hier doch wohl zu eng!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2333, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Vorsicht! Spreng dich hier drinnen" "\x11" "blo" "\x96" " nicht in die Luft..." "\x11" "Ich scherze nicht!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2334, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "N" "\xA8" ", ich kenne keinen solchen Jun-" "\x11" "gen. Der Gesch" "\x9A" "ftsf" "\xAC" "hrer ist auch" "\x11" "nicht da, ich kann dir also wirklich" "\x11" "nicht weiterhelfen." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2335, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6C" "Was'n das f" "\xAC" "r'n d" "\x9A" "mliches Ding?" "\x11" "So etwas w" "\xAC" "rde ich nie tragen," "\x11" "also wird's wohl nix mit einer" "\x11" "Mitgliedschaft..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2336, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ich hab an dem Preisausschreiben" "\x11" "teilgenommen, um ein paar Kon-" "\x11" "zert-Karten zu gewinnen... Du hast" "\x11" "nicht zuf" "\x9A" "llig was f" "\xAC" "r mich?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2337, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "Oh! Wenn ich auch erst ein M" "\x9A" "d-" "\x11" "chen gefunden habe und verheira-" "\x11" "tet bin..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2338, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "Wow! Ist das ein Sch" "\x9A" "del?" "\x11" "Ziemlich abgefahren!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2339, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "..." "\x11" "\x13" "\x13" "\x12" "Hier schauen nur wenige Kunden" "\x11" "herein... Ich frage mich, womit der" "\x11" "Boss so viel Kohle scheffelt?!?" "\xE0" "\xBF" "", NULL);
